from pathlib import Path
path = Path('pydantic/_internal/_std_types_schema.py')
text = path.read_text()
old = """    def to_enum(input_value: Any, /) -> Enum:
        try:
            return enum_type(input_value)
        except ValueError:
            raise PydanticCustomError('enum', 'Input should be {expected}', {'expected': expected})
"""
new = """    value2member_map = enum_type._value2member_map_
    missing = enum_type._missing_
    # EnumMeta.__call__ is relatively expensive, especially for invalid inputs since it
    # builds and raises a ValueError.  For the common case of hashable enum values we can
    # use Enum's cached value->member map directly.  We still fall back to EnumMeta for
    # unhashable values and for enums with a custom _missing_ implementation to preserve
    # stdlib enum semantics.
    default_missing = getattr(missing, '__func__', missing) is getattr(Enum._missing_, '__func__', Enum._missing_)

    def to_enum(input_value: Any, /) -> Enum:
        if isinstance(input_value, enum_type):
            return input_value

        try:
            return value2member_map[input_value]
        except KeyError:
            if default_missing:
                raise PydanticCustomError('enum', 'Input should be {expected}', {'expected': expected})
        except TypeError:
            # Unhashable values require EnumMeta's slower linear search over
            # _unhashable_values_ before considering _missing_.
            pass

        try:
            return enum_type(input_value)
        except ValueError:
            raise PydanticCustomError('enum', 'Input should be {expected}', {'expected': expected})
"""
if old not in text:
    raise SystemExit('old block not found')
path.write_text(text.replace(old, new))
