from enum import Enum, IntEnum
from pydantic import TypeAdapter, ValidationError

class IntE(IntEnum):
    A=1; B=2
class StrE(Enum):
    X='x'; Y='y'
class OneE(Enum):
    ONLY='singleton'
    @classmethod
    def _missing_(cls, value): return cls.ONLY
class NoneMissing(Enum):
    A='a'
    @classmethod
    def _missing_(cls, value): return None
class BadMissing(Enum):
    A='a'
    @classmethod
    def _missing_(cls, value): return 'bad'
class ValueErrorMissing(Enum):
    A='a'
    @classmethod
    def _missing_(cls, value): raise ValueError('boom')
class RuntimeErrorMissing(Enum):
    A='a'
    @classmethod
    def _missing_(cls, value): raise RuntimeError('boom')
class U(Enum):
    A=[]

assert TypeAdapter(IntE).validate_python(1) is IntE.A
try: TypeAdapter(IntE).validate_python(3)
except ValidationError: pass
else: raise AssertionError('expected ValidationError')
