assert TypeAdapter(OneE).validate_python('anything') is OneE.ONLY
for cls in (NoneMissing, ValueErrorMissing):
    try: TypeAdapter(cls).validate_python('x')
    except ValidationError: pass
    else: raise AssertionError(f'expected ValidationError for {cls}')
try: TypeAdapter(BadMissing).validate_python('x')
except TypeError: pass
else: raise AssertionError('expected TypeError')
try: TypeAdapter(RuntimeErrorMissing).validate_python('x')
except RuntimeError: pass
else: raise AssertionError('expected RuntimeError')
assert TypeAdapter(U).validate_python([]) is U.A
print('quick enum checks ok')
